    public static void MathGlsl6MatchesNative()   // packing (GLSL 8.4, glm's packing.hpp)
    {
        for (int iteration = 0; iteration < 40; ++iteration)
        {
            {
                var a0 = PF();
                var m = KMath.FloatToHalf(a0);
                var n = KoralMathNative.koral_float_to_half(a0);
                Check.That(PSame(m, n, true), "koral_float_to_half");
            }
            {
                var a0 = PH();
                var m = KMath.HalfToFloat(a0);
                var n = KoralMathNative.koral_half_to_float(a0);
                Check.That(PSame(m, n, true), "koral_half_to_float");
            }
            {
                var a0 = new Vec4(PF(), PF(), PF(), PF());
                var m = KMath.PackUnorm4x8(a0);
